export const localizedPrivacy: Partial<Record<Locale, PrivacyCopy>> = Object.fromEntries(Object.entries(privacySections).map(([locale, sections]) => {
  const key = locale as keyof typeof privacySections;
  const [title, description, intro, updated, googleLabel] = privacyIntro[key];
  const labelsFor = labels[key];
  return [locale, { title, description, intro, updated, sections: sections.map(([title, body]) => ({ title, body })), googleLabel, moneyLabel: labelsFor[0] }];
})) as Partial<Record<Locale, PrivacyCopy>>;

export const localizedTerms: Partial<Record<Locale, TermsCopy>> = Object.fromEntries(Object.entries(termsSections).map(([locale, sections]) => {
  const key = locale as keyof typeof termsSections;
  const [title, description, intro, privacyLabel] = termsIntro[key];
  const [moneyLabel, home, privacy, terms, footer] = labels[key];
  return [locale, { title, description, intro, sections: sections.map(([title, body]) => ({ title, body })), privacyLabel, moneyLabel, home, privacy, terms, footer }];
})) as Partial<Record<Locale, TermsCopy>>;

